import {buildPlan,validateEvent} from './planner.mjs';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(n);
const pretty=s=>new Date(s+'T12:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'});
const today=()=>new Date().toLocaleDateString('en-CA');
const sampleEvent={name:'A celebration to remember',type:'Wedding',date:'2027-01-15',location:'Kochi, Kerala',budget:500000,guests:150,preferences:'An intimate garden celebration. Seasonal flowers, vegetarian food, warm lighting and step-free access.'};
const sampleIdeas=[{title:'A garden, softly glowing',description:'Pair seasonal greenery with reusable lanterns and warm lighting. Keep a covered indoor alternative for rain.',category:'Atmosphere'},{title:'A little taste of home',description:'Offer a thoughtfully labeled vegetarian menu with regional favourites. Ask guests about dietary requirements before confirming.',category:'Food & connection'},{title:'Memories that travel home',description:'Invite guests to leave a handwritten wish. Photograph the notes and turn them into a simple digital keepsake.',category:'Personal touches'}];
let plan={...buildPlan(sampleEvent,'2026-10-20'),ideas:sampleIdeas},sample=true,ideasSource='Sample ideas',tab='Overview',notice='',error='',busy=false,aiReady=false,answer='',editMode=false;
try{const raw=localStorage.getItem('gatherly-v1');if(raw){const saved=JSON.parse(raw);validateEvent(saved.plan.event);if(!['budget','tasks','vendors','ideas'].every(k=>Array.isArray(saved.plan[k])))throw Error();if(!saved.plan.budget.every(b=>Number.isFinite(b.amount)&&Number.isFinite(b.spent)&&b.amount>=0&&b.spent>=0))throw Error();plan=saved.plan;sample=saved.sample;ideasSource=saved.ideasSource||'Saved ideas';}}catch{notice='Could not restore the saved plan. A sample is shown.';}
function save(){try{localStorage.setItem('gatherly-v1',JSON.stringify({plan,sample,ideasSource}));}catch{notice='Browser storage is unavailable. Export your plan to keep a copy.';}}
const nav=[['Overview','◫'],['Budget','◷'],['Timeline','☷'],['Vendors','⌂'],['Ideas studio','✧']];
const tasks=items=>items.map(t=>`<label class="task ${t.done?'complete':''}"><input type="checkbox" data-task="${esc(t.id)}" ${t.done?'checked':''}><span class="task-copy"><strong>${esc(t.title)}</strong><small>${esc(t.category)}</small></span><time datetime="${esc(t.date)}">${pretty(t.date)}</time></label>`).join('');
function overview(){const done=plan.tasks.filter(t=>t.done).length,spent=plan.budget.reduce((s,b)=>s+b.spent,0),total=plan.budget.reduce((s,b)=>s+b.amount,0),days=Math.max(0,Math.ceil((Date.parse(plan.event.date+'T23:59:59')-Date.now())/86400000));return `<section class="event-hero"><div class="hero-copy"><span class="pill">● ${esc(plan.event.type.toUpperCase())} PLAN</span><h2>${esc(plan.event.name)}</h2><p>A thoughtful plan. A beautiful day.<br>And all the space to enjoy it.</p><div class="event-meta"><span>▦ ${pretty(plan.event.date)}</span><span>⌖ ${esc(plan.event.location)}</span><span>♧ ${plan.event.guests} guests</span></div><button class="button cream" data-action="edit">Edit event details ↗</button></div><div class="hero-art" aria-hidden="true"><div class="art-circle"></div><div class="stem stem-a"></div><div class="stem stem-b"></div><div class="stem stem-c"></div><div class="petal bloom-a">✳</div><div class="petal bloom-b">✳</div><div class="petal bloom-c">✳</div><div class="vase"></div><span class="art-star star-a">✧</span><span class="art-star star-b">✦</span><div class="countdown"><strong>${days}</strong><span>DAYS TO THE<br>GOOD TIMES</span></div></div></section><section class="stats" aria-label="Event summary"><div class="stat"><span class="stat-icon">◷</span><p>Total budget</p><strong>${money(plan.event.budget)}</strong><small>${money(plan.event.budget-spent)} left to spend</small></div><div class="stat"><span class="stat-icon rose">♧</span><p>Guest list</p><strong>${plan.event.guests}<em>people</em></strong><small>About ${money(plan.event.budget/plan.event.guests)} per guest</small></div><div class="stat"><span class="stat-icon gold">☷</span><p>Planning progress</p><strong>${done}<em>/ ${plan.tasks.length} tasks</em></strong><div class="progress"><span style="width:${done/plan.tasks.length*100}%"></span></div></div><div class="stat"><span class="stat-icon lilac">⌂</span><p>Vendor team</p><strong>${plan.vendors.filter(v=>v.status==='Booked').length}<em>/ ${plan.vendors.length} booked</em></strong><small>Your celebration crew</small></div></section><div class="two-col"><section class="panel"><div class="section-head"><div><p class="eyebrow">ONE STEP AT A TIME</p><h2>Next on your list</h2></div><button class="text-btn" data-tab="Timeline">View timeline →</button></div>${tasks(plan.tasks.filter(t=>!t.done).slice(0,3))||'<p class="empty">Everything is checked off. Time to celebrate!</p>'}</section><section class="idea-invite"><span class="sparkle">✧</span><p class="eyebrow">A LITTLE INSPIRATION</p><h2>Make it feel<br>like you.</h2><p>Thoughtful themes, meaningful moments and ideas made for your celebration.</p><button class="button dark" data-tab="Ideas studio">Explore ideas ↗</button></section></div><section class="panel budget-preview"><div class="section-head"><div><p class="eyebrow">CELEBRATE WITH CONFIDENCE</p><h2>Your budget at a glance</h2></div><button class="text-btn" data-tab="Budget">Manage budget →</button></div><div class="budget-bar" aria-label="Budget allocation">${plan.budget.map((b,i)=>`<span class="color-${i}" style="width:${total?b.amount/total*100:0}%" title="${esc(b.name)}: ${money(b.amount)}"></span>`).join('')}</div><div class="legend">${plan.budget.map((b,i)=>`<span><i class="color-${i}"></i>${esc(b.name)}<strong>${money(b.amount)}</strong></span>`).join('')}</div></section>`;}
function budget(){const allocated=plan.budget.reduce((s,b)=>s+b.amount,0),spent=plan.budget.reduce((s,b)=>s+b.spent,0);return `<section class="panel"><div class="budget-summary">${[['Event budget',plan.event.budget],['Allocated',allocated],['Spent',spent],['Available',plan.event.budget-spent]].map(([k,v])=>`<div><p>${k}</p><h2 class="${v<0?'warning':''}">${money(v)}</h2></div>`).join('')}</div>${allocated!==plan.event.budget?`<p class="notice">${allocated>plan.event.budget?'Allocations exceed your budget by '+money(allocated-plan.event.budget):money(plan.event.budget-allocated)+' is unallocated.'}</p>`:''}<div class="table-wrap"><table><caption>Budget estimates in Indian rupees. Replace estimates with vendor quotes.</caption><thead><tr><th scope="col">Category</th><th scope="col">Allocated (₹)</th><th scope="col">Spent (₹)</th><th scope="col">Remaining</th></tr></thead><tbody>${plan.budget.map((b,i)=>`<tr><th scope="row"><i class="dot color-${i}"></i>${esc(b.name)}</th><td><input aria-label="${esc(b.name)} allocated rupees" type="number" min="0" max="100000000" data-budget="${i}" data-field="amount" value="${b.amount}"></td><td><input aria-label="${esc(b.name)} spent rupees" type="number" min="0" max="100000000" data-budget="${i}" data-field="spent" value="${b.spent}"></td><td class="${b.spent>b.amount?'warning':''}">${money(b.amount-b.spent)}</td></tr>`).join('')}</tbody></table></div><p class="footnote">Initial allocations include 10% contingency. These are planning estimates, not market quotes. Vendor quotes are tracked separately and do not automatically count as spending.</p></section>`;}
function timeline(){const done=plan.tasks.filter(t=>t.done).length;return `<section class="panel"><div class="section-head"><div><p class="eyebrow">YOUR ROAD TO THE CELEBRATION</p><h2>${done} of ${plan.tasks.length} little wins</h2></div><span class="tag">${Math.round(done/plan.tasks.length*100)}% complete</span></div><div class="progress full"><span style="width:${done/plan.tasks.length*100}%"></span></div>${tasks(plan.tasks)}<form id="task-form" class="inline-form"><label>One more thing to do<input name="title" required maxlength="160" placeholder="Add a personal task"></label><label>Due date<input type="date" name="date" required value="${esc(plan.event.date)}"></label><button class="button primary">Add task +</button></form><p class="footnote">For events planned at short notice, earlier preparation tasks move to today.</p></section>`;}
function vendors(){return `<div class="vendor-grid">${plan.vendors.map((v,i)=>`<section class="panel vendor-card"><div class="section-head"><h2>${esc(v.category)}</h2><span class="vendor-number color-${i}">0${i+1}</span></div><label>Vendor name<input data-vendor="${i}" data-field="name" value="${esc(v.name)}" maxlength="100" placeholder="Add your shortlist"></label><div class="form-row"><label>Status<select data-vendor="${i}" data-field="status">${['To shortlist','Contacted','Quote received','Booked'].map(s=>`<option ${v.status===s?'selected':''}>${s}</option>`).join('')}</select></label><label>Quote (₹)<input type="number" data-vendor="${i}" data-field="quote" min="0" max="100000000" value="${v.quote}"></label></div><label>Questions & notes<textarea data-vendor="${i}" data-field="notes" maxlength="1000" placeholder="Availability, inclusions, deposit, cancellation terms…">${esc(v.notes)}</textarea></label></section>`).join('')}</div>`;}
function ideas(){return `<section class="panel ai-panel"><span class="pill">✧ ${aiReady?'OPENAI CONNECTED':'AI CONNECTION PENDING'}</span><h2>A celebration with your signature.</h2><p>Personal touches, practical suggestions and budget-conscious ideas based on your event details.</p><p class="preference">“${esc(plan.event.preferences||'Add preferences in your event details for more personal ideas.')}”</p><button class="button primary" data-action="ideas" ${busy?'disabled':''}>✧ ${busy?'Thinking of something lovely…':'Generate personalized ideas'}</button>${!aiReady?'<p class="footnote">Live AI is not connected yet. Budget, timeline and vendor tools work independently. Sample ideas are labeled below.</p>':''}<p class="footnote">Generating ideas or asking a question sends event details and your message to OpenAI. Avoid private or sensitive information.</p></section><div class="ideas-grid">${plan.ideas.map((idea,i)=>`<article class="idea-card idea-${i%3}"><span class="idea-symbol" aria-hidden="true">${['✳','✧','❋'][i%3]}</span><span class="eyebrow">${esc(idea.category)}</span><h2>${esc(idea.title)}</h2><p>${esc(idea.description)}</p><small>${esc(ideasSource)}</small></article>`).join('')||'<p class="empty">Your inspiration will appear here after generating ideas.</p>'}</div><section class="panel chat"><h2>Ask your planning assistant</h2><p>“How can we reduce décor costs?” or “Suggest an accessible welcome activity.”</p><form id="chat-form"><label class="sr-only" for="question">Your planning question</label><input id="question" name="question" required maxlength="800" placeholder="What would you like help with?"><button class="button primary" ${busy?'disabled':''}>Ask assistant →</button></form>${answer?`<div class="answer" role="status">${esc(answer)}</div>`:''}</section>`;}
function render(){const heads={Overview:['Make room for the celebration.','The details, the to-dos, the little touches. All together in one happy place.'],Budget:['Every rupee, thoughtfully planned.','Set a realistic budget, track spending, and keep a little breathing room.'],Timeline:['A little closer to your big day.','Clear next steps, from your first idea to the last happy goodbye.'],Vendors:['Your dream team, coming together.','Keep your shortlists, quotes and questions in one place.'],'Ideas studio':['A spark of something special.','Personal ideas to make your celebration feel unmistakably yours.']};$('#app').innerHTML=`<div class="app"><aside class="sidebar"><a href="#main" class="logo"><span>✳</span>gatherly<sup>✳</sup></a><div class="workspace-label">YOUR PLANNING SPACE</div><nav aria-label="Planner navigation">${nav.map(([name,icon])=>`<button class="nav ${tab===name?'active':''}" data-tab="${name}" ${tab===name?'aria-current="page"':''}><span>${icon}</span>${name}${name==='Ideas studio'?'<small class="ai-tag">AI</small>':''}</button>`).join('')}</nav><div class="sidebar-note"><span class="mini-flower">✳</span><h3>Less planning stress.<br>More happy moments.</h3><p>A little structure makes room for a lot of joy.</p><button data-action="new">Plan something lovely ↗</button></div><div class="profile"><span class="avatar">G</span><div><strong>Your event workspace</strong><small>Saved on this device</small></div><span class="online"></span></div></aside><div class="content"><header class="topbar"><div><span class="breadcrumb">My workspace</span><span>›</span><strong>${tab}</strong></div><div class="top-actions"><span class="saved">● Saved locally</span><button class="button primary" data-action="new">+ New event</button></div></header><main id="main" tabindex="-1"><div class="heading"><p class="eyebrow">GOOD THINGS START WITH A PLAN</p><h1>${heads[tab][0]}</h1><p>${heads[tab][1]}</p></div>${notice?`<div class="notice" role="status">${esc(notice)}<button data-action="dismiss" aria-label="Dismiss notification">×</button></div>`:''}${sample?'<div class="sample"><span>EXAMPLE WORKSPACE</span>Explore this sample wedding, or create your own event.<button data-action="new">Make it yours →</button></div>':''}${error?`<div class="error" role="alert">${esc(error)}</div>`:''}${({Overview:overview,Budget:budget,Timeline:timeline,Vendors:vendors,'Ideas studio':ideas})[tab]()}<footer><span>✳ Thoughtfully planned. Joyfully celebrated.</span><div><button data-action="export">↓ Export plan</button><button data-action="print">▤ Print view</button></div></footer></main></div></div>`;}
function openForm(edit){editMode=edit;const e=edit?plan.event:{...sampleEvent,name:'',date:new Date(Date.now()+90*86400000).toISOString().slice(0,10),preferences:''};for(const [k,v] of Object.entries(e))$('#event-form').elements[k].value=v;$('#event-form').elements.date.min=today();$('#form-error').hidden=true;$('#event-dialog').showModal();$('#event-form').elements.name.focus();}
$('#close-modal').addEventListener('click',()=>$('#event-dialog').close());
$('#event-form').addEventListener('submit',e=>{e.preventDefault();try{const data=Object.fromEntries(new FormData(e.target));data.budget=Number(data.budget);data.guests=Number(data.guests);validateEvent(data);const next=buildPlan(data,today());if(editMode){next.vendors=plan.vendors;next.tasks=next.tasks.map(t=>({...t,done:plan.tasks.find(x=>x.id===t.id)?.done||false})).concat(plan.tasks.filter(t=>t.id.startsWith('custom-')));next.budget=next.budget.map((b,i)=>({...b,spent:plan.budget[i]?.spent||0}));}plan=next;sample=false;ideasSource='';answer='';error='';notice='Your plan is ready. Adjust estimates when you receive real quotes.';tab='Overview';save();$('#event-dialog').close();render();$('#main').focus();}catch(err){$('#form-error').hidden=false;$('#form-error').textContent=err.message;}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.tab){tab=b.dataset.tab;error='';render();document.querySelector('button.nav[aria-current="page"]')?.focus();}const a=b.dataset.action;if(a==='new')openForm(false);if(a==='edit')openForm(true);if(a==='dismiss'){notice='';render();}if(a==='print')window.print();if(a==='export'){const url=URL.createObjectURL(new Blob([JSON.stringify(plan,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='gatherly-event-plan.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}if(a==='ideas')askAI('ideas','');});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.task){const task=plan.tasks.find(x=>x.id===t.dataset.task);if(task)task.done=t.checked;save();render();document.querySelector(`[data-task="${t.dataset.task}"]`)?.focus();}if(t.dataset.budget!==undefined){const n=Number(t.value);if(!Number.isFinite(n)||n<0||n>100000000){t.reportValidity();return;}plan.budget[Number(t.dataset.budget)][t.dataset.field]=Math.round(n);save();render();document.querySelector(`[data-budget="${t.dataset.budget}"][data-field="${t.dataset.field}"]`)?.focus();}if(t.dataset.vendor!==undefined){const v=plan.vendors[Number(t.dataset.vendor)];const value=t.dataset.field==='quote'?Math.min(100000000,Math.max(0,Number(t.value)||0)):t.value;v[t.dataset.field]=value;save();}});
document.addEventListener('submit',e=>{if(e.target.id==='chat-form'){e.preventDefault();askAI('chat',new FormData(e.target).get('question'));}if(e.target.id==='task-form'){e.preventDefault();const data=Object.fromEntries(new FormData(e.target));if(!data.title.trim())return;plan.tasks.push({id:'custom-'+crypto.randomUUID(),title:data.title.trim(),date:data.date,category:'Personal task',done:false});save();render();}});
async function askAI(mode,question){busy=true;error='';render();try{const r=await fetch('/api/ideas',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({event:plan.event,mode,question})});if(!r.headers.get('content-type')?.includes('application/json'))throw Error('Live AI is not connected on this deployment. The planner tools remain available.');const d=await r.json();if(!r.ok)throw Error(d.error||'Generation failed. Please try again.');if(mode==='ideas'){plan.ideas=d.ideas;ideasSource='Generated with OpenAI';save();notice='Personalized ideas are ready.';}else answer=d.answer;}catch(err){error=err.message;}finally{busy=false;render();}}
render();fetch('/api/ideas').then(r=>r.ok&&r.headers.get('content-type')?.includes('application/json')?r.json():{}).then(d=>{aiReady=Boolean(d.configured);if(tab==='Ideas studio')render();}).catch(()=>{});
